WITH q1 AS (
SELECT COUNT(Id) FROM votes WHERE YEAR(CreationDate) = 2010
),
q2 AS (
SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2011'
),
q3 AS (
SELECT (SELECT CAST(COUNT(Id) AS REAL) FROM votes WHERE strftime('%Y', CreationDate) = '2010') / (SELECT COUNT(Id) FROM votes WHERE strftime('%Y', CreationDate) = '2011')
)
SELECT * FROM q3

WITH q1 AS (
    SELECT Id, Count FROM tags WHERE Id < 15
),
q2 AS (
    SELECT Id, Count FROM tags WHERE Id < 15 AND Count <= 20
),
q3 AS (
    SELECT COUNT(*) AS TagCount FROM q2
)
SELECT TagCount FROM q3

WITH q1 AS (
SELECT district_id FROM district WHERE A3 = 'Prague'
),
q2 AS (
SELECT account_id FROM account WHERE district_id IN (SELECT district_id FROM district WHERE A3 = 'Prague')
),
q3 AS (
SELECT DISTINCT account_id FROM loan
),
q4 AS (
SELECT COUNT(*) AS eligible_accounts FROM q2 WHERE account_id NOT IN (SELECT account_id FROM q3)
)
SELECT eligible_accounts FROM q4

WITH q1 AS (
SELECT expense_description, SUM(cost) AS total_cost FROM expense GROUP BY expense_description
),
q2 AS (
SELECT expense_description, COUNT(expense_id) AS expense_count FROM expense GROUP BY expense_description
),
q3 AS (
SELECT expense_description, SUM(cost) / COUNT(expense_id) AS avg_spend FROM expense GROUP BY expense_description
),
q4 AS (
SELECT expense_description, SUM(cost) / COUNT(expense_id) AS avg_spend FROM expense GROUP BY expense_description HAVING SUM(cost) / COUNT(expense_id) > 50
)
SELECT expense_description FROM q4

WITH q1 AS (
SELECT SUM(weight_kg) AS total_weight FROM superhero WHERE full_name = 'Emil Blonsky'
),
q2 AS (
SELECT SUM(weight_kg) AS total_weight FROM superhero WHERE full_name = 'Charles Chandler'
),
q3 AS (
SELECT (SELECT SUM(weight_kg) FROM superhero WHERE full_name = 'Emil Blonsky') - (SELECT SUM(weight_kg) FROM superhero WHERE full_name = 'Charles Chandler') AS weight_difference
)
SELECT weight_difference FROM q3

WITH q1 AS (
SELECT COUNT(*) AS total_bad_superheroes FROM superhero WHERE alignment_id = 2
),
q2 AS (
SELECT COUNT(*) AS female_bad_superheroes FROM superhero WHERE alignment_id = 2 AND gender_id = 2
),
q3 AS (
SELECT CAST(q2.female_bad_superheroes AS REAL) / q1.total_bad_superheroes * 100.0 AS percentage_female_bad_superheroes FROM q1 CROSS JOIN q2
)
SELECT percentage_female_bad_superheroes FROM q3

WITH q1 AS (
SELECT COUNT(ID) FROM Patient WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31'
),
q2 AS (
SELECT COUNT(ID) FROM Patient WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31' AND Admission = '+'
